window.kbPageData["cards/d3ab537c1791fab6d04110e0"] = {"qs":{"江苏 2025 A类 行测#104":{"paper":"江苏 2025 A类 行测","n":104,"mod":"判断推理","src":["98687766ac277f427cd6.pdf",22],"asrc":["4fe8e0544dd7b47699d2.pdf",34],"m":["2ee4494e7734239c"],"task":"结合赛道方位、名次和车色线索，推断选手与籍贯及名次的对应关系。","current_affairs":{"state":"否","event":null,"year":null,"basis":"作答依据为题内比赛线索。"},"links":[{"id":"s-aa16640dd943508a","label":"按多条约束确定对应或次序","catalog_id":"L02","type":null,"role":"直接考查","field":"M1","quote":"安徽选手排在骑黄色自行车的选手之前，排在选手甲之后。","why":"将相对次序与已知方位、名次及籍贯交叉约束，确定选手的对应关系。","origin":"逐题标记"}],"stem":"根据上述信息，可以推出以下哪项？","options":["甲来自江苏，排第二位","乙来自浙江，排第四位","丙来自安徽，排第一位","丁来自上海，排第三位"],"answer":"B","analysis":"104. 正确答案：B\n解析：\n第一步：分析题干条件。\n（1）江苏选手在选手丙的东南面；\n（2）上海选手在赛道的东部位置，他所骑自行车是蓝色的；\n（3）骑灰色自行车的选手不是排在第四位；\n（4）选手丁排在第三位，选手乙来自浙江；\n（5）安徽选手排在骑黄色自行车的选手之前，排在选手甲之后。\n第二步：根据题干条件进行推理。\n根据条件（1）江苏选手在丙的东南面，可以推出丙是第2名，江苏选手是第3名；\n根据条件（2）上海选手在赛道东部以及江苏选手是第3名，可以推出上海选手是第1名，且自行车是蓝色的；\n根据条件（3）以及第1名自行车是蓝色的，可以推出灰色自行车的选手不是第2名，就是第3名；\n根据条件（4）以及江苏选手是第3名，可以推出丁是江苏选手；\n根据条件（5）、上海选手是第1名以及江苏选手是第3名，可以推出安徽选手是第2名，甲是第1名，具体如下表所\n示。\n\n\n\n\n综合上述结论，可以推出第4名是乙，来自浙江，B项当选。\n故正确答案为B。\n【考点】\n材料-其他,从确定信息开始推或其他（材料）","figs":[],"state":"已标记","notes":[],"domains":["形式逻辑"],"nature":"技能题","current":false},"江苏 2025 A类 行测#105":{"paper":"江苏 2025 A类 行测","n":105,"mod":"判断推理","src":["98687766ac277f427cd6.pdf",22],"asrc":["4fe8e0544dd7b47699d2.pdf",34],"m":["2ee4494e7734239c"],"task":"将丙骑白色自行车这一附加条件与原有约束合用，推断籍贯与车色的对应关系。","current_affairs":{"state":"否","event":null,"year":null,"basis":"作答依据为题内比赛线索和附加假设。"},"links":[{"id":"s-aa16640dd943508a","label":"按多条约束确定对应或次序","catalog_id":"L02","type":null,"role":"直接考查","field":"answer","quote":"骑灰色自行车的选手不是排在第四位","why":"将新增车色条件代入已确定的选手与名次对应关系，按名次限制排除剩余车色分配。","origin":"逐题标记"}],"stem":"如果丙所骑自行车是白色，则可以推出以下哪项？","options":["选手甲所骑自行车不是蓝色的","选手乙所骑自行车是灰色的","安徽选手所骑自行车是黄色的","江苏选手所骑自行车是灰色的"],"answer":"D","analysis":"105. 正确答案：D\n\n解析：\n第一步：分析题干条件。\n（1）江苏选手在选手丙的东南面；\n（2）上海选手在赛道的东部位置，他所骑自行车是蓝色的；\n（3）骑灰色自行车的选手不是排在第四位；\n（4）选手丁排在第三位，选手乙来自浙江；\n（5）安徽选手排在骑黄色自行车的选手之前，排在选手甲之后；\n（6）丙的自行车是白色的。\n第二步：根据题干条件进行推理。\n根据上一题的结论，第1名为选手甲，来自上海，自行车是蓝色的，排除A项；\n根据条件（6）丙的自行车是白色的，结合上一题的结论可以推出第2名为选手丙，来自安徽，自行车是白色的，排\n除C项；\n再根据条件（3）骑灰色自行车的选手不是排在第四位，结合上一题的结论可以推出第3名选手丁来自江苏，自行车\n是灰色的，那么第4名选手乙来自浙江，自行车是黄色的（具体如下表所示），D项当选。\n\n\n\n\n故正确答案为D。\n【考点】\n材料-其他,排除法（材料）","figs":[],"state":"已标记","notes":[],"domains":["形式逻辑"],"nature":"技能题","current":false},"江苏 2025 A类 行测#106":{"paper":"江苏 2025 A类 行测","n":106,"mod":"判断推理","src":["98687766ac277f427cd6.pdf",22],"asrc":["4fe8e0544dd7b47699d2.pdf",35],"m":[],"task":"核对各治理案例中的参与主体及其合作方式，判断哪项符合题内多元共治的定义。","current_affairs":{"state":"否","event":null,"year":null,"basis":"依据题内定义和给定案例即可判定。"},"links":[{"id":"s-conditions","label":"按题内定义核对案例条件","catalog_id":"L04","type":null,"role":"直接考查","field":"answer","quote":"政府、社会组织、公民等主体共同参与","why":"按定义识别案例中的参与方，并核对不同类型的主体是否共同参与治理。","origin":"逐题标记"}],"stem":"多元共治：指针对社会运行中的复杂问题，由政府、社会组织、公民等主体共同参与，多方合作的社会治理模\n式。\n下列属于多元共治的是：","options":["针对辖区内河道持续多年的污染问题，某县水利、环保等部门成立联合工作小组，决心打赢河道污染治理的攻坚\n战","针对居民停车位、充电桩严重不足的问题，某街道统筹规划电动自行车停放充电区域，优化地下非机动车库安全\n设施，消除电动自行车“上楼入户”的隐患","某区政府在老旧小区改造、公共服务等社区工作中，鼓励业委会、志愿者充分发挥各自作用，遇到问题加强沟\n通，满足居民的合理诉求","某村两面临山，农林交错，靠近交通要道，火灾防治压力巨大。村民自发组织巡查队，检测上报森林火情，有效\n遏制了火灾多发的势头"],"answer":"C","analysis":"106. 正确答案：C\n解析：\n第一步：找出定义关键词。\n“政府、社会组织、公民等主体共同参与”、“多方合作的社会治理模式”。\n第二步：逐一分析选项。\nA项：某县水利、环保等部门联合治理河道污染，不涉及社会组织和公民等主体，不符合“政府、社会组织、公民等\n主体共同参与”，不符合定义，排除；\nB项：某街道统筹规划电动自行车停放充电区域，优化地下非机动车库安全设施，不涉及社会组织和公民等主体，不\n符合“政府、社会组织、公民等主体共同参与”、“多方合作的社会治理模式”，不符合定义，排除；\nC项：某区政府在社区工作中，鼓励业委会、志愿者充分发挥各自作用，符合“政府、社会组织、公民等主体共同参\n与”、“多方合作的社会治理模式”，符合定义，当选；\nD项：村民自发组织巡查队，检测上报森林火情，不涉及政府等主体，不符合“政府、社会组织、公民等主体共同参\n与”、“多方合作的社会治理模式”，不符合定义，排除。\n故正确答案为C。\n【考点】\n主客体","figs":[],"state":"已标记","notes":[],"domains":["社会治理"],"nature":"技能题","current":false}},"materialFiles":{"2ee4494e7734239c":"6fcb0a419152ea0cc0496357"},"terms":{"s-aa16640dd943508a":{"id":"s-aa16640dd943508a","mode":"s","type":"判断推理","title":"多条件对应与排序","qs":[],"count":71},"s-conditions":{"id":"s-conditions","mode":"s","type":"判断推理","title":"按题内定义核对案例条件","qs":[],"count":149}},"questions":{}};
